begin;
select no_plan();
insert into auth.users(id) values('00000000-0000-4000-8000-000000000051');
insert into public.control_center_owner(owner_user_id) values('00000000-0000-4000-8000-000000000051');
select set_config('request.jwt.claim','',true);
select set_config('request.jwt.claim.sub','',true);
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000051","aal":"aal2"}',true);
insert into public.tenants(id,category,legal_name,created_by,updated_by)
select ('10000000-0000-4000-8000-' || lpad(n::text,12,'0'))::uuid,'internal','Create test '||n,'00000000-0000-4000-8000-000000000051','00000000-0000-4000-8000-000000000051' from generate_series(1,20) n;
set local role authenticated;
select lives_ok($q$select public.create_license('10000000-0000-4000-8000-000000000001','mini');set constraints all immediate$q$,'owner AAL2 creates complete default graph');
set constraints all deferred;
select lives_ok($q$select public.create_license('10000000-0000-4000-8000-000000000002','standard',clock_timestamp()+interval '1 day',clock_timestamp()+interval '2 days','00000000-0000-4000-8000-000000000051');set constraints all immediate$q$,'future finite Standard graph');
set constraints all deferred;
select lives_ok($q$select public.create_license('10000000-0000-4000-8000-000000000003','stor');set constraints all immediate$q$,'Stor graph');
set constraints all deferred;
reset role;
select is((select count(*)::integer from public.licenses),3,'three successful licenses');
select ok(bool_and(status='draft' and revision=1 and current_terms_version=1 and created_by='00000000-0000-4000-8000-000000000051' and updated_by='00000000-0000-4000-8000-000000000051' and created_at=updated_at),'exact license state actor and timestamps') from public.licenses;
select ok(bool_and(a.actor_user_id=l.created_by and a.occurred_at=l.created_at and a.event_type='license_created' and a.revision_before is null and a.revision_after=1),'audit identity revision and shared decision time') from public.licenses l join public.license_audit_events a on a.license_id=l.id;
select ok(bool_and(t.version=1 and t.introduced_at_revision=1 and t.plan_version=1),'terms revision/version') from public.license_terms_versions t;
select results_eq($q$select plan_key,plan_display_label,max_active_users from public.license_terms_versions order by max_active_users$q$,$q$select * from (values('mini'::text,'Mini'::text,24),('standard','Standard',49),('stor','Stor',100)) v$q$,'canonical snapshots for all packages');
select ok(bool_and(t.valid_from=l.created_at and t.valid_until is null),'default start equals decision time and end indefinite') from public.licenses l join public.license_terms_versions t on t.license_id=l.id where l.tenant_id<>'10000000-0000-4000-8000-000000000002';
select ok(t.valid_from>l.created_at and t.valid_until>t.valid_from and a.correlation_id='00000000-0000-4000-8000-000000000051','future interval and correlation') from public.licenses l join public.license_terms_versions t on t.license_id=l.id join public.license_audit_events a on a.license_id=l.id where l.tenant_id='10000000-0000-4000-8000-000000000002';
select ok(bool_and(a.correlation_id is null),'default correlation null') from public.licenses l join public.license_audit_events a on a.license_id=l.id where l.tenant_id<>'10000000-0000-4000-8000-000000000002';
select is(a.changed_fields,array_remove(array['id','tenant_id','status','revision','current_terms_version','plan_key','plan_version','plan_display_label','max_active_users','valid_from',case when t.valid_until is not null then 'valid_until' end,'created_at','created_by','updated_at','updated_by']::text[],null),'exact canonical changed_fields '||t.plan_key) from public.license_audit_events a join public.license_terms_versions t on t.license_id=a.license_id;
set local role authenticated;
select throws_ok($q$select public.create_license(null,'mini')$q$,'22023','validation_error','null tenant');
select throws_ok($q$select public.create_license('10000000-0000-4000-8000-000000000004',null)$q$,'22023','validation_error','null plan');
select throws_ok($q$select public.create_license('10000000-0000-4000-8000-000000000004','custom')$q$,'22023','validation_error','invalid plan custom');
select throws_ok($q$select public.create_license('10000000-0000-4000-8000-000000000004','Mini')$q$,'22023','validation_error','invalid plan Mini');
select throws_ok($q$select public.create_license('10000000-0000-4000-8000-000000000004',' mini')$q$,'22023','validation_error','invalid plan  mini');
select throws_ok($q$select public.create_license('10000000-0000-4000-8000-000000000004','')$q$,'22023','validation_error','invalid plan ');
select throws_ok($q$select public.create_license('10000000-0000-4000-8000-000000000004','mini',clock_timestamp()-interval '1 second')$q$,'22023','validation_error','past start');
select throws_ok($q$select public.create_license('10000000-0000-4000-8000-000000000004','mini','2099-01-01','2099-01-01')$q$,'22023','validation_error','end equals start');
select throws_ok($q$select public.create_license('10000000-0000-4000-8000-000000000004','mini','2099-01-02','2099-01-01')$q$,'22023','validation_error','end before start');
select throws_ok($q$select public.create_license('10000000-0000-4000-8000-000000000004','mini','infinity')$q$,'22023','validation_error','infinite start infinity');
select throws_ok($q$select public.create_license('10000000-0000-4000-8000-000000000004','mini',null,'infinity')$q$,'22023','validation_error','infinite end infinity');
select throws_ok($q$select public.create_license('10000000-0000-4000-8000-000000000004','mini','-infinity')$q$,'22023','validation_error','infinite start -infinity');
select throws_ok($q$select public.create_license('10000000-0000-4000-8000-000000000004','mini',null,'-infinity')$q$,'22023','validation_error','infinite end -infinity');
select throws_ok($q$select public.create_license('10000000-0000-4000-8000-000000000099','mini')$q$,'P0001','not_found','missing tenant');
reset role;
update public.tenants set operational_status='paused' where id='10000000-0000-4000-8000-000000000004';
update public.tenants set archived_at=clock_timestamp(),archived_by='00000000-0000-4000-8000-000000000051' where id='10000000-0000-4000-8000-000000000005';
set local role authenticated;
select throws_ok($q$select public.create_license('10000000-0000-4000-8000-000000000004','mini')$q$,'P0001','tenant_not_available','unavailable Tenant 4');
select throws_ok($q$select public.create_license('10000000-0000-4000-8000-000000000005','mini')$q$,'P0001','tenant_not_available','unavailable Tenant 5');
reset role;
-- Test fixtures change only administrative status; F2D4 is structural, not lifecycle validation.
update public.licenses set status='active' where tenant_id='10000000-0000-4000-8000-000000000002';
update public.licenses set status='suspended' where tenant_id='10000000-0000-4000-8000-000000000003';
set local role authenticated;
select throws_ok($q$select public.create_license('10000000-0000-4000-8000-000000000001','mini')$q$,'P0001','duplicate_license','existing draft blocks');
select throws_ok($q$select public.create_license('10000000-0000-4000-8000-000000000002','mini')$q$,'P0001','duplicate_license','existing active blocks');
select throws_ok($q$select public.create_license('10000000-0000-4000-8000-000000000003','mini')$q$,'P0001','duplicate_license','existing suspended blocks');
reset role;
select is((select count(*)::integer from public.licenses),3,'all rejected requests preserve license count');
select is((select count(*)::integer from public.license_terms_versions),3,'all rejected requests preserve terms count');
select is((select count(*)::integer from public.license_audit_events),3,'all rejected requests preserve audit count');
update public.licenses set status='terminated' where tenant_id='10000000-0000-4000-8000-000000000001';
set local role authenticated;
select lives_ok($q$select public.create_license('10000000-0000-4000-8000-000000000001','mini');set constraints all immediate$q$,'terminated history permits new draft');
set constraints all deferred;
reset role;
select is((select count(*)::integer from public.licenses where tenant_id='10000000-0000-4000-8000-000000000001'),2,'terminated history retained');
-- Transaction-scoped constraint probes: no trigger disabling or product test hooks.
set constraints all immediate;
set constraints all deferred;
alter table public.license_audit_events add constraint test_reject_audit check(event_type<>'license_created') not valid;
select throws_ok($q$select public.create_license('10000000-0000-4000-8000-000000000006','mini')$q$,'P0001','audit_failure','audit insert failure rolls back create');
alter table public.license_audit_events drop constraint test_reject_audit;
alter table public.license_terms_versions add constraint test_reject_terms check(max_active_users>100) not valid;
select throws_ok($q$select public.create_license('10000000-0000-4000-8000-000000000006','mini')$q$,'23514',null,'terms failure propagates and rolls back create');
alter table public.license_terms_versions drop constraint test_reject_terms;
select throws_ok($q$select public.create_license('10000000-0000-4000-8000-000000000006','mini');update public.licenses set revision=2 where tenant_id='10000000-0000-4000-8000-000000000006';set constraints all immediate$q$,'23514','license history integrity violation','deferred failure rolls back entire attempted transaction');
select is((select count(*)::integer from public.licenses),4,'no partial license after injected failures');
select is((select count(*)::integer from public.license_terms_versions),4,'no partial terms after injected failures');
select is((select count(*)::integer from public.license_audit_events),4,'no partial audit after injected failures');
select lives_ok('set constraints all immediate','remaining graph valid');
select * from finish();
rollback;
